import React, { useState, useRef } from 'react';
import axios from 'axios';

const EnhancedBillUpload = ({ onUploadSuccess }) => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [processingStatus, setProcessingStatus] = useState(null);
  const fileInputRef = useRef(null);

  // Check processing status on component mount
  React.useEffect(() => {
    checkProcessingStatus();
  }, []);

  const checkProcessingStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/bills/processing-status', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProcessingStatus(response.data);
    } catch (error) {
      console.error('Error checking processing status:', error);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFile(e.dataTransfer.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleFileSelect = (e) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setUploading(true);
    setError(null);
    setResult(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:8000/upload',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setResult(response.data);
      setFile(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      
      // Call the success callback if provided
      if (onUploadSuccess) {
        onUploadSuccess(response.data);
      }
    } catch (error) {
      console.error('Upload error:', error);
      setError(
        error.response?.data?.detail || 
        'An error occurred while processing the bill'
      );
    } finally {
      setUploading(false);
    }
  };

  const removeFile = () => {
    setFile(null);
    setError(null);
    setResult(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (filename) => {
    const ext = filename.split('.').pop()?.toLowerCase();
    const iconMap = {
      'pdf': '📄',
      'jpg': '🖼️',
      'jpeg': '🖼️',
      'png': '🖼️',
      'gif': '🖼️',
      'bmp': '🖼️',
      'tiff': '🖼️'
    };
    return iconMap[ext] || '📎';
  };

  return (
    <div className="enhanced-bill-upload">
      <div className="upload-header">
        <h2>📤 Upload New Bill</h2>
        <p>Upload your expense receipts for intelligent processing and approval</p>
      </div>

      {/* File Upload Area */}
      <div className="upload-section">
        <h3>📁 File Selection</h3>
        <p className="section-description">
          Drag and drop your bill image or PDF here, or click to browse files
        </p>
        
        <div 
          className={`file-drop-area ${dragActive ? 'drag-active' : ''}`}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
        >
          <div className="file-drop-content">
            <div className="file-icon">📁</div>
            <div className="file-drop-text">
              <h4>Drop your bill file here</h4>
              <p>or click to browse files</p>
            </div>
            <div className="file-types">
              Supported formats: JPG, PNG, PDF, GIF, BMP, TIFF
            </div>
            <div className="file-size-limit">
              Maximum file size: 10MB
            </div>
          </div>
        </div>

        <input
          ref={fileInputRef}
          type="file"
          onChange={handleFileSelect}
          accept=".jpg,.jpeg,.png,.gif,.bmp,.tiff,.pdf"
          style={{ display: 'none' }}
        />
      </div>

      {/* Selected File Display */}
      {file && (
        <div className="selected-file-section">
          <h3>📋 Selected File</h3>
          <div className="selected-file-info">
            <div className="file-details">
              <div className="file-icon-large">
                {getFileIcon(file.name)}
              </div>
              <div className="file-info">
                <h4 className="file-name">{file.name}</h4>
                <p className="file-meta">
                  Size: {formatFileSize(file.size)} • 
                  Type: {file.type || 'Unknown'} • 
                  Last modified: {new Date(file.lastModified).toLocaleDateString()}
                </p>
              </div>
            </div>
            <div className="file-actions">
              <button 
                className="btn btn-secondary"
                onClick={removeFile}
                disabled={uploading}
              >
                🗑️ Remove
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Upload Button */}
      {file && (
        <div className="upload-actions">
          <button 
            className={`btn btn-primary ${uploading ? 'disabled' : ''}`}
            onClick={handleUpload}
            disabled={uploading || !file}
          >
            {uploading ? (
              <div className="upload-loading">
                <div className="loading-spinner"></div>
                <span>Processing Bill...</span>
              </div>
            ) : (
              <div className="upload-text">
                <span>🚀</span>
                <span>Process Bill</span>
              </div>
            )}
          </button>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div className="error-section">
          <h3>❌ Error</h3>
          <div className="error-content">
            <p className="error-message">{error}</p>
            <button 
              className="btn btn-secondary"
              onClick={() => setError(null)}
            >
              Dismiss
            </button>
          </div>
        </div>
      )}

      {/* Results Display */}
      {result && (
        <div className="results-section">
          <h3>✅ Bill Processed Successfully</h3>
          
          <div className="results-grid">
            <div className="result-card">
              <h4>💰 Amount</h4>
              <div className="result-value amount">
                {result.bill_data?.amount ? 
                  new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: 'USD'
                  }).format(result.bill_data.amount) : 'N/A'
                }
              </div>
            </div>
            
            <div className="result-card">
              <h4>📅 Date</h4>
              <div className="result-value">
                {result.bill_data?.date || 'N/A'}
              </div>
            </div>
            
            <div className="result-card">
              <h4>🏪 Vendor</h4>
              <div className="result-value">
                {result.bill_data?.vendor || 'N/A'}
              </div>
            </div>
            
            <div className="result-card">
              <h4>📂 Category</h4>
              <div className="result-value">
                {result.bill_data?.category || 'N/A'}
              </div>
            </div>
          </div>

          {result.bill_data?.subtotal && (
            <div className="financial-breakdown">
              <h4>💰 Financial Breakdown</h4>
              <div className="breakdown-grid">
                <div className="breakdown-item">
                  <span className="breakdown-label">Subtotal:</span>
                  <span className="breakdown-value">
                    {new Intl.NumberFormat('en-US', {
                      style: 'currency',
                      currency: 'USD'
                    }).format(result.bill_data.subtotal)}
                  </span>
                </div>
                {result.bill_data.tax && (
                  <div className="breakdown-item">
                    <span className="breakdown-label">Tax:</span>
                    <span className="breakdown-value">
                      {new Intl.NumberFormat('en-US', {
                        style: 'currency',
                        currency: 'USD'
                      }).format(result.bill_data.tax)}
                    </span>
                  </div>
                )}
                {result.bill_data.discount && (
                  <div className="breakdown-item">
                    <span className="breakdown-label">Discount:</span>
                    <span className="breakdown-value">
                      {new Intl.NumberFormat('en-US', {
                        style: 'currency',
                        currency: 'USD'
                      }).format(result.bill_data.discount)}
                    </span>
                  </div>
                )}
                <div className="breakdown-item full-width">
                  <span className="breakdown-label">Total:</span>
                  <span className="breakdown-value total">
                    {new Intl.NumberFormat('en-US', {
                      style: 'currency',
                      currency: 'USD'
                    }).format(result.bill_data.amount)}
                  </span>
                </div>
              </div>
            </div>
          )}

          {result.bill_data?.payment_method && (
            <div className="payment-info">
              <h4>💳 Payment Information</h4>
              <div className="payment-details">
                <span><strong>Method:</strong> {result.bill_data.payment_method}</span>
                {result.bill_data.invoice_number && (
                  <span><strong>Invoice:</strong> {result.bill_data.invoice_number}</span>
                )}
              </div>
            </div>
          )}

          {result.bill_data?.confidence_score && (
            <div className="confidence-info">
              <h4>🎯 Processing Confidence</h4>
              <div className="confidence-bar">
                <div 
                  className="confidence-fill"
                  style={{ width: `${(result.bill_data.confidence_score * 100)}%` }}
                ></div>
              </div>
              <p className="confidence-text">
                Confidence Score: {(result.bill_data.confidence_score * 100).toFixed(1)}%
              </p>
            </div>
          )}

          <div className="result-actions">
            <button 
              className="btn btn-primary"
              onClick={() => {
                setResult(null);
                setFile(null);
                if (fileInputRef.current) {
                  fileInputRef.current.value = '';
                }
              }}
            >
              📤 Upload Another Bill
            </button>
          </div>
        </div>
      )}

      {/* Processing Status */}
      {processingStatus && (
        <div className="processing-status">
          <h3>⚙️ System Status</h3>
          <div className="status-grid">
            <div className="status-item">
              <span className="status-label">OCR Service:</span>
              <span className={`status-value ${processingStatus.ocr_status === 'healthy' ? 'healthy' : 'unhealthy'}`}>
                {processingStatus.ocr_status === 'healthy' ? '✅ Healthy' : '❌ Unhealthy'}
              </span>
            </div>
            <div className="status-item">
              <span className="status-label">AI Processing:</span>
              <span className={`status-value ${processingStatus.ai_status === 'healthy' ? 'healthy' : 'unhealthy'}`}>
                {processingStatus.ai_status === 'healthy' ? '✅ Healthy' : '❌ Unhealthy'}
              </span>
            </div>
            <div className="status-item">
              <span className="status-label">Database:</span>
              <span className={`status-value ${processingStatus.database_status === 'healthy' ? 'healthy' : 'unhealthy'}`}>
                {processingStatus.database_status === 'healthy' ? '✅ Healthy' : '❌ Unhealthy'}
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EnhancedBillUpload;
